from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class MerchantGatewayConfigView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, merchant_id):
        if not request.user.merchants.filter(id=merchant_id, role="admin").exists():
            return Response({"error": "Forbidden"}, status=403)

        setting_key = f"PAYMENT_GATEWAY_SECRET_{merchant_id}"
        secret = getattr(config, setting_key, None)
        if secret is None:
            return Response({"error": "Configuration not found"}, status=404)

        return Response({
            "merchant_id": merchant_id,
            "secret_key": secret,
            "webhook_endpoint": getattr(config, f"PAYMENT_WEBHOOK_{merchant_id}", "")
        })
